import { trpc } from "@/lib/trpc";
import { ArrowDownRight, ArrowUpRight, BarChart3, Boxes, Check, ChevronRight, CircleDollarSign, Database, Download, FileDown, Filter, Package, Plus, Printer, Search, ShoppingCart, Sparkles, TrendingUp, Truck, Users, WalletCards, X, RotateCcw, ReceiptText } from "lucide-react";
import { Bar, BarChart, CartesianGrid, Cell, Legend, Pie, PieChart, ResponsiveContainer, Tooltip, XAxis, YAxis } from "recharts";
import * as XLSX from "xlsx";
import { useEffect, useMemo, useState } from "react";
import { useLocation } from "wouter";
import { toast } from "sonner";
import DashboardLayout from "@/components/DashboardLayout";
import { createReportWorkbook } from "@shared/exportWorkbook";
import { BanglaInvoicePrint, ThermalReceipt, type PrintSale } from "@/components/PrintTemplates";
